import { useEffect, useRef, type ReactNode } from 'react';

/*
 * Signature 1: spotlit product stage. Lit stages may arm the settle-in motion (landing and feature
 * sections only); quiet stages are static and their window is unfaded.
 */
interface StageProps {
  children: ReactNode;
  quiet?: boolean;
  below?: boolean;
  /** Arm the settle-in entry (landing and feature sections only). */
  armed?: boolean;
  ghost?: ReactNode;
  /** Demo windows are inert and hidden from assistive tech; a real chart stays accessible. */
  demo?: boolean;
  className?: string;
  windowClassName?: string;
}

export function Stage({ children, quiet, below, armed, ghost, demo = true, className, windowClassName }: StageProps) {
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!armed || !el || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    el.classList.add('is-armed');
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          el.classList.add('is-in');
          io.disconnect();
        }
      },
      { threshold: 0.2 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [armed]);

  const cls = ['stage', quiet && 'stage--quiet', below && 'stage--below', className].filter(Boolean).join(' ');
  return (
    <figure ref={ref} className={cls}>
      {ghost && !quiet && (
        <div className="stage-window stage-ghost" aria-hidden="true" inert>
          {ghost}
        </div>
      )}
      <div
        className={['stage-window', windowClassName].filter(Boolean).join(' ')}
        aria-hidden={demo ? 'true' : undefined}
        inert={demo || undefined}
      >
        {children}
      </div>
    </figure>
  );
}

/** Figure caption: mono "FIG" number, the item name, one fact. */
export function Fig({ number, name, children }: { number: string; name: string; children: ReactNode }) {
  return (
    <p className="fig">
      <span className="mono-label">FIG {number}</span>
      <span>
        <b>{name}</b> {children}
      </span>
    </p>
  );
}
EOF
