import { useMemo } from 'react';

/** Renders a string built with blueprint() (see ./blueprint.ts). The svg itself is aria-hidden. */
export function Blueprint({ svg, lifted = false }: { svg: string; lifted?: boolean }) {
  const html = useMemo(() => (lifted ? svg.replace('class="bp ', 'class="bp is-lifted ') : svg), [svg, lifted]);
  return <span className="bp-host" dangerouslySetInnerHTML={{ __html: html }} />;
}
EOF
