import type { ReactNode } from 'react';

/*
 * Signature 5: working shimmer and live edges. Only while something really runs: swap these
 * for plain text the moment the work ends.
 */
export function Shimmer({ children, running = true }: { children: ReactNode; running?: boolean }) {
  return <span className={running ? 'shimmer' : 'shimmer-settled'}>{children}</span>;
}

export function LiveEdge({ children, running = true, className }: { children: ReactNode; running?: boolean; className?: string }) {
  return <span className={[running ? 'live-edge' : 'live-edge-settled', className].filter(Boolean).join(' ')}>{children}</span>;
}

/** A live dot whose ring grows and fades; stale data shows a still idle dot. */
export function Pulse({ stale = false }: { stale?: boolean }) {
  return <span className={stale ? 'pulse pulse--stale' : 'pulse'} aria-hidden="true" />;
}

export function Caret() {
  return <span className="caret" aria-hidden="true" />;
}
EOF
