import type { ReactNode } from 'react';

/*
 * Signature 6: split opener, two-tone voice, mono figures. App screens use ScreenHead; settings
 * groups use SettingsGroup (counter, title and description left, controls right).
 */
export function TwoTone({ lead, children }: { lead: ReactNode; children?: ReactNode }) {
  return (
    <p className="two-tone">
      <b>{lead}</b>
      {children ? <> {children}</> : null}
    </p>
  );
}

export function ScreenHead({ label, title, children }: { label: string; title: string; children?: ReactNode }) {
  return (
    <header className="screen-head">
      <div className="screen-head-title">
        <p className="mono-label">{label}</p>
        <h1>{title}</h1>
      </div>
      <div className="screen-head-summary">{children}</div>
    </header>
  );
}

export function Opener({ title, children, link }: { title: string; children: ReactNode; link?: ReactNode }) {
  return (
    <div className="opener">
      <h2>{title}</h2>
      <div>
        <p>{children}</p>
        {link && <p className="opener-link">{link}</p>}
      </div>
    </div>
  );
}

interface SettingsGroupProps {
  index: number;
  total: number;
  title: string;
  titleId?: string;
  description?: ReactNode;
  children: ReactNode;
  as?: 'section' | 'div';
}

/** A split settings row as a section; for fieldsets, see the matching markup in NotificationsPage. */
export function SettingsGroup({ index, total, title, titleId, description, children, as = 'section' }: SettingsGroupProps) {
  const Tag = as;
  return (
    <Tag className="settings-group" aria-labelledby={as === 'section' ? titleId : undefined}>
      <div className="group-head">
        <GroupCounter index={index} total={total} />
        <h2 id={titleId} className="group-title">
          {title}
        </h2>
        {description && <p className="group-description">{description}</p>}
      </div>
      <div className="group-body">{children}</div>
    </Tag>
  );
}

export function GroupCounter({ index, total }: { index: number; total: number }) {
  const pad = (n: number) => String(n).padStart(2, '0');
  return (
    <span className="mono-label group-counter" aria-hidden="true">
      {pad(index)} / {pad(total)}
    </span>
  );
}
EOF
